import httpx
from x402.client import PaymentClient  # coinbase/x402 Python SDK

client = PaymentClient(wallet=agent_wallet)  # agent_wallet signs EIP-3009 USDC payloads

def fetch_paid_resource(url: str) -> dict:
    resp = client.get(url)           # client auto-handles 402 -> sign -> retry
    resp.raise_for_status()
    return resp.json()

# Spend guard: reject if this session has already exceeded budget
def guarded_fetch(url: str, session_budget_usdc: float, spent: float) -> dict:
    if spent >= session_budget_usdc:
        raise RuntimeError('x402 session budget exhausted')
    return fetch_paid_resource(url)

MAINNET_CHAIN_IDS = {'base-mainnet', 'ethereum', 'arbitrum-one', 'optimism', 'polygon-mainnet'}

def assert_trade_allowed(network_id: str, escalation_approved: bool) -> None:
    """Raise before any CDP Trade API call if mainnet execution is not yet approved."""
    if network_id in MAINNET_CHAIN_IDS and not escalation_approved:
        raise RuntimeError(
            f'CDP Trade blocked on {network_id}: paper-gate not cleared. '
            'Set escalation_approved only after written human approval.'
        )
